	@ParameterizedTest
	@CsvSource({ "0,2,1", "1,-1,2", "2,1,1" })
	void optionalPreservesRowsConsumedBySlice(long offset, long limit, String count) {
		MapBindingSet leftFirst = new MapBindingSet();
		leftFirst.setBinding("x", iri("urn:first"));
		MapBindingSet leftSecond = new MapBindingSet();
		leftSecond.setBinding("x", iri("urn:second"));
		MapBindingSet rightFirst = new MapBindingSet();
		rightFirst.setBinding("unused", iri("urn:right1"));
		MapBindingSet rightSecond = new MapBindingSet();
		rightSecond.setBinding("unused", iri("urn:right2"));
		LeftJoin input = new LeftJoin(assignment(Set.of("x"), leftFirst, leftSecond),
				assignment(Set.of("unused"), rightFirst, rightSecond));
		Group source = new Group(new Slice(input, offset, limit), List.of(),
				List.of(new GroupElem("count", new Count(Var.of("x"), true))));
		assertEquals(List.of(Map.of("count", count)), normalized(evaluate(source, List.of())));
		assertEquivalentAlternatives(source, List.of(), PackedRuleProofs.REMOVE_UNUSED_OPTIONAL, false);
	}

